entries[22219] = { ["name"] = "Plans: Jagged Obsidian Shield", ["text"] = "Binds when picked up\nRequires Blacksmithing (300)\nRequiresCenarion Circle\n- Revered\nUse: Teaches you how to make a Jagged Obsidian Shield.\nJagged Obsidian Shield\nBinds when equipped\nOff Hand Shield\n2645 Armor\n48 Block\nDurability 120 / 120\nRequires Level 60\nEquip: Increases your chance to block attacks with a shield by 2%.\nEquip: +5 All Resistances.\nEquip: When struck by a harmful spell, the caster of that spell has a 5% chance to be silenced for 3 sec. (Proc chance: 5%, 20s cooldown)\nRequires Large Obsidian Shard (8), Small Obsidian Shard (24), Enchanted Thorium Bar (8), Essence of Earth (4)" }
entries[22220] = { ["name"] = "Plans: Black Grasp of the Destroyer", ["text"] = "Requires Blacksmithing (300)\nUse: Teaches you how to make the Black Grasp of the Destroyer.\nBlack Grasp of the Destroyer\nBinds when equipped\nHands Mail\n279 Armor\nDurability 50 / 50\nRequires Level 60\nEquip: +28 Attack Power.\nEquip: Improves your chance to get a critical strike by 1%.\nEquip: On successful melee or ranged attack gain 8 mana and if possible drain 8 mana from the target.\nRequires Large Obsidian Shard (8), Small Obsidian Shard (24), Enchanted Leather (8), Flask of Supreme Power" }
entries[22221] = { ["name"] = "Plans: Obsidian Mail Tunic", ["text"] = "Binds when picked up\nRequires Blacksmithing (300)\nRequiresCenarion Circle\n- Exalted\nUse: Teaches you how to make an Obsidian Mail Tunic.\nObsidian Mail Tunic\nBinds when equipped\nChest Mail\n458 Armor\nDurability 140 / 140\nRequires Level 60\nEquip: +76 Attack Power.\nEquip: Improves your chance to get a critical strike by 1%.\nEquip: Spell Damage received is reduced by 10.\nRequires Large Obsidian Shard (15), Small Obsidian Shard (36), Enchanted Leather (12), Guardian Stone (10), Azerothian Diamond (4)" }
entries[22222] = { ["name"] = "Plans: Thick Obsidian Breastplate", ["text"] = "Requires Blacksmithing (300)\nUse: Teaches you how to make a Thick Obsidian Breastplate.\nThick Obsidian Breastplate\nBinds when equipped\nChest Plate\n814 Armor\n+38 Strength\n+16 Stamina\nDurability 165 / 165\nRequires Level 60\nEquip: When struck by a non-periodic damage spell you have a 30% chance of getting a 6 sec spell shield that absorbs 300 to 500 of that school of damage. (Proc chance: 30%, 10s cooldown)\nRequires Large Obsidian Shard (18), Small Obsidian Shard (40), Enchanted Thorium Bar (12), Essence of Earth (10), Huge Emerald (4)" }
