entries[22630] = { ["name"] = "Atiesh, Greatstaff of the Guardian", ["text"] = "Binds when picked up\nTwo-Hand Staff\n130 - 243 Damage Speed 2.90\n(64.31 damage per second)\n+30 Stamina\n+29 Intellect\nDurability 145 / 145\nClasses: Warlock\nRequires Level 60\nEquip: Improves your chance to get a critical strike with spells by 2%.\nEquip: Increases damage and healing done by magical spells and effects by up to 150.\nEquip: Increases damage and healing done by magical spells and effects of all party members within 30 yards by up to 33.\nUse: Creates a portal, teleporting group members that use it to Karazhan. (1 Min Cooldown)" }
